{
  "microtasks": [
    {
      "id": 1,
      "description": "Define the overall research design, specifying and justifying the mixed-methods approach.",
      "prerequisites": []
    },
    {
      "id": 2,
      "description": "Define the target population (undergraduate students) and the sampling strategy for recruitment.",
      "prerequisites": []
    },
    {
      "id": 3,
      "description": "Detail the survey instrument, including the types of questions, scales used, and variables measured.",
      "prerequisites": []
    },
    {
      "id": 4,
      "description": "Detail the semi-structured interview protocol, including the core themes and sample questions.",
      "prerequisites": []
    },
    {
      "id": 5,
      "description": "Write the step-by-step procedure for administering the survey (e.g., platform, distribution channels, timeline).",
      "prerequisites": [3]
    },
    {
      "id": 6,
      "description": "Write the step-by-step procedure for conducting the interviews (e.g., format, recording, transcription).",
      "prerequisites": [4]
    },
    {
      "id": 7,
      "description": "Draft the ethical considerations, covering informed consent, participant anonymity, and institutional approval.",
      "prerequisites": [5, 6]
    },
    {
      "id": 8,
      "description": "Outline the quantitative data analysis plan for the survey data (e.g., statistical tests, software).",
      "prerequisites": [3]
    },
    {
      "id": 9,
      "description": "Outline the qualitative data analysis plan for the interview transcripts (e.g., thematic analysis, coding process).",
      "prerequisites": [4]
    },
    {
      "id": 10,
      "description": "Draft the 'Participants and Sampling' subsection of the methodology.",
      "prerequisites": [2]
    },
    {
      "id": 11,
      "description": "Draft the 'Materials and Instruments' subsection, describing the survey and interview guide.",
      "prerequisites": [3, 4]
    },
    {
      "id": 12,
      "description": "Draft the 'Procedure' subsection, integrating the data collection steps and ethical considerations.",
      "prerequisites": [5, 6, 7]
    },
    {
      "id": 13,
      "description": "Draft the 'Data Analysis' subsection, combining the quantitative and qualitative analysis plans.",
      "prerequisites": [8, 9]
    },
    {
      "id": 14,
      "description": "Synthesize all drafted subsections (Participants, Instruments, Procedure, Analysis) into a single cohesive Methodology draft.",
      "prerequisites": [1, 10, 11, 12, 13]
    },
    {
      "id": 15,
      "description": "Review and edit the complete Methodology section for academic tone, clarity, and alignment with the research questions.",
      "prerequisites": [14]
    }
  ]
}
